package com.zubaer.maxvideoplayer.playback

import android.content.Context
import android.util.Base64
import java.io.File

internal object AndroidTestMediaFixture {
    fun writeShortH264Mp4(context: Context, fileName: String): File =
        File(context.cacheDir, fileName).apply {
            writeBytes(Base64.decode(SAMPLE_MP4_BASE64, Base64.NO_WRAP))
        }

    private const val SAMPLE_MP4_BASE64 = ""
}
